data.transform:
(
  $L := $state.context.LOCAL;
  $customer := $L.customer;
  $facility := $L.facility;
  $id := $string($L.trx[0].id);
  $fuuzId:= $cuid();
  $formatData:=
  {
    "so": {
        "create": $L.trx[mainline='T'].(
          $e := $string(entity);
          $ll := $string(location);
          {
            "id": $fuuzId,
            "externalId": $id,
            "customerId": $customer[externalId=$e].id,
            "customerOrderNumber":otherrefnum,
            "number": tranid,
            "issuedAt": $moment(trandate),
            "dueAt": $isNilOrEmpty(expectedshipdate) ? ($isNilOrEmpty(shipdate) ? $moment() : $moment(shipdate)) : $moment(expectedshipdate),
            "salesOrderTypeId": "Spot Order",
            "salesOrderStatusId": "Pending Fulfillment",
            "facilityId": $facility[externalId=$ll].id,
            "integrationData": $,
            "sCustomerAddressId":$customer.edges.node.sCustomerAddress.id,
            "bCustomerAddressId":$customer.edges.node.bCustomerAddress.id
          }
        )
      },
      "sol": $L.trx[mainline = "F"].{
        "create": (
          $i:=$string(item);
          $l:=$string(location);
          {
            "id":$cuid(),
            "externalId":$string(uniquekey),
            "code": $string(tranid) & ":"
              & $string(linesequencenumber),
            "number": $string(linesequencenumber),
            "quantity": {
              "value": 0 - quantity,
              "unitId": $string(units)
            },
            "balanceQuantity": {
              "value": 0 - quantity, 
              "unitId": $string(units)
            },
            "shippedQuantity": {
              "value": 0,
              "unitId": $string(units)
            },
            "expectedShipAt": $isNilOrEmpty(expectedshipdate) ? ($isNilOrEmpty(shipdate) ? $moment() : $moment(shipdate)) : $moment(expectedshipdate),
            "shipAt": $isNilOrEmpty(expectedshipdate) ? ($isNilOrEmpty(shipdate) ? $moment() : $moment(shipdate)) : $moment(expectedshipdate),
            "dueAt": $isNilOrEmpty(expectedshipdate) ? ($isNilOrEmpty(shipdate) ? $moment() : $moment(shipdate)) : $moment(expectedshipdate),
            "productId": $L.product[externalId=$i].id,
            "productStrategyId":$L.product[externalId=$i].strategies.edges.node.id,
            "productStrategyProcessId": $L.product[externalId=$i].strategies.edges.node.strategyProcesses.edges.node.id,
            "salesOrderLineStatusId": "Pending Fulfillment",
            "salesOrderId": $fuuzId,
            "facilityId": $facility[externalId=$l].id,
            "integrationData": $,
            "sCustomerAddressId":$customer.edges.node.sCustomerAddress.id,
            "bCustomerAddressId":$customer.edges.node.bCustomerAddress.id
          }
        )
      }

    };
    {
    "so":[$formatData.so],
    "sol":[$formatData.sol],
    "soLineRelease":[ $formatData.sol.create.{
        "create": (
          {
            "releaseNo":number,
            "quantity": quantity.value,
            /* "balanceQuantity": balanceQuantity.value, created via data model expression*/
            "shippedQuantity": shippedQuantity.value,
            "scheduledQuantity":0,
            "expectedShipAt": expectedShipAt,
            "shipAt": shipAt,
            "dueAt": dueAt,
            /* "productId": productId, */
            /* "productStrategyProcessId": productStrategyProcessId, */
            "salesOrderLineReleaseStatusId": "Pending",
            "salesOrderLineStatusId":"Pending Fulfillment",
            "salesOrderLineReleaseTypeId":$L.salesOrderLineReleaseType.id,
            "salesOrderLineId": id,
            "integrationData": integrationData
          }
        )
      }]
    }
)

data.query:
query Query($where: SalesOrderStatusWhereInput) {
  status:salesOrderStatus(where: $where) {
    edges {
      node {
        id
        name
        externalId
      }
    }
  }
}

query ($so: SalesOrderWhereInput, $product: ProductWhereInput, $customer: CustomerWhereInput, $unit: UnitWhereInput, $facility: FacilityWhereInput, $strategyWhere: ProductStrategyWhereInput, $whereReleaseType: SalesOrderLineReleaseTypeWhereInput) {
  so: salesOrder(where: $so) {
    edges {
      node {
        id
        externalId
        lines {
          edges {
            node {
              id
              shipmentLines {
                edges {
                  node {
                    id
                  }
                }
              }
            }
          }
        }
        shipments {
          edges {
            node {
              id
            }
          }
        }
      }
    }
  }
  product(where: $product) {
    edges {
      node {
        id
        externalId
        productTypeId
        strategies(where: $strategyWhere) {
          edges {
            node {
              id
              facility {
                id
                code
              }
              strategyProcesses(where: {final: {_eq: true}}) {
                edges {
                  node {
                    id
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  customer(where: $customer) {
    edges {
      node {
        id
        externalId
        sCustomerAddress :customerAddresses (where:{defaultShipping:{_eq:true}},first:1) {
          edges {
            node {
              id
              code
            }
          }
        }
        bCustomerAddress :customerAddresses (where:{defaultBilling:{_eq:true}},first:1) {
          edges {
            node {
              id
              code
            }
          }
        }
      }
    }
  }
  unit(where: $unit) {
    edges {
      node {
        id
      }
    }
  }
  facility(where: $facility) {
    edges {
      node {
        id
        externalId
      }
    }
  }
  salesOrderLineReleaseType(where: $whereReleaseType, first: 1) {
    edges {
      node {
        id
        name
      }
    }
  }
}

